function typeformProblemReport({ response }) {
  if (!response || !Array.isArray(response.answers) || !Array.isArray(response.definition?.fields))
    throw new Error("Expected a complete Typeform problem report");
  const read = (title, type) => {
    const fields = response.definition.fields.filter((field) => field?.title === title);
    if (
      fields.length !== 1 ||
      typeof fields[0].id !== "string" ||
      !fields[0].id ||
      response.definition.fields.filter((field) => field?.id === fields[0].id).length !== 1
    )
      throw new Error("The " + title + " question must identify one field");
    const answers = response.answers.filter((answer) => answer?.field?.id === fields[0].id);
    if (answers.length !== 1 || answers[0].type !== type)
      throw new Error("Expected one " + type + " answer for " + title);
    return answers[0][type];
  };
  const report = {
    Email: read("Email", "email"),
    Name: read("Name", "text"),
    Severity: read("Severity", "number"),
    Problem: read("Problem", "text"),
  };
  for (const key of ["Email", "Name", "Problem"])
    if (typeof report[key] !== "string" || !report[key].trim())
      throw new Error("The " + key + " answer must contain text");
  if (!/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(report.Email))
    throw new Error("The Email answer must contain an email address");
  if (typeof report.Severity !== "number" || !Number.isFinite(report.Severity))
    throw new Error("The Severity answer must be a finite number");
  return {
    report,
    values: [[report.Email, report.Name, String(report.Severity), report.Problem]],
    message:
      "Email: " +
      report.Email +
      "\nName: " +
      report.Name +
      "\nSeverity: " +
      report.Severity +
      "\n\nProblem:\n" +
      report.Problem,
    urgent: report.Severity > 7,
  };
}

return $input.all().flatMap((item, index) =>
  item.json.event_type === "form_response"
    ? [
        {
          json: typeformProblemReport({ response: item.json.form_response }).report,
          pairedItem: { item: index },
        },
      ]
    : [],
);

function problemSlackConfirmed({ ts, channelId, report, log }) {
  if (typeof ts !== "string" || !ts.trim() || typeof channelId !== "string" || !channelId.trim())
    throw new Error("Slack did not return a saved message identity");
  return { route: "slack", report, log, notification: { ts, channelId } };
}

return {
  json: problemSlackConfirmed({
    ts: $json.ts,
    channelId: $json.channel,
    report: $("Read the problem report").first().json,
    log: { range: "Problems!A:D", appended: true },
  }),
};

function problemEmailConfirmed({ messageId, accepted, rejected, response, report, log }) {
  if (
    !Array.isArray(accepted) ||
    !Array.isArray(rejected) ||
    rejected.length ||
    !accepted.length ||
    accepted.some((value) => typeof value !== "string" || !value.trim())
  )
    throw new Error("SMTP did not accept every configured recipient");
  if (messageId != null && typeof messageId !== "string")
    throw new Error("SMTP returned an invalid Message-ID");
  if (typeof response !== "string") throw new Error("SMTP did not return a submission response");
  return { route: "email", report, log, notification: { messageId, accepted, rejected, response } };
}

return {
  json: problemEmailConfirmed({
    ...$json,
    report: $("Read the problem report").first().json,
    log: { range: "Problems!A:D", appended: true },
  }),
};
